function fail(message, details = []) {
  return [{ json: { ok: false, status: 'Rechazada', message, details } }];
}

let sale;
try {
  const raw = $json.body || $json;
  sale = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  return fail('La venta no tiene un formato valido.');
}

const operationId = String(sale.operationId || `pos-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`);
const items = Array.isArray(sale.items) ? sale.items : [];
const paymentMethod = String(sale.paymentMethod || '').trim();
const allowedPayments = ['cash', 'card', 'transfer'];

if (items.length === 0) return fail('La venta no tiene productos.');
if (!allowedPayments.includes(paymentMethod)) return fail('Selecciona un metodo de pago valido.');

const normalizedItems = [];
for (const item of items) {
  const quantity = Number(item.quantity || 0);
  const unitPrice = Number(item.unitPrice || 0);
  const productId = String(item.productId || '').trim();
  if (!productId) return fail('Hay un producto sin identificador.');
  if (!Number.isFinite(quantity) || quantity <= 0) return fail('Hay un producto con cantidad invalida.');
  if (!Number.isFinite(unitPrice) || unitPrice < 0) return fail('Hay un producto con precio invalido.');
  normalizedItems.push({
    productId,
    name: String(item.name || ''),
    barcode: String(item.barcode || ''),
    unitPrice,
    weight: Number(item.weight || 0),
    quantity,
    lineTotal: unitPrice * quantity
  });
}

const subtotal = normalizedItems.reduce((sum, item) => sum + item.lineTotal, 0);
const discountPercent = Math.min(100, Math.max(0, Number(sale.discountPercent || 0)));
const discountAmount = subtotal * (discountPercent / 100);
const total = subtotal - discountAmount;
const clientTotal = Number(sale.total || 0);
const cashReceived = Number(sale.cashReceived || 0);

if (Math.abs(clientTotal - total) > 1) return fail('El total de la venta no coincide con el calculo del servidor.');
if (paymentMethod === 'cash' && cashReceived < total) return fail('El efectivo recibido no alcanza para cubrir el total.');
if (total <= 0) return fail('El total de la venta debe ser mayor a cero.');

const productFormula = `OR(${normalizedItems.map(item => `RECORD_ID() = "${item.productId.replace(/"/g, '\\"')}"`).join(', ')})`;
const duplicateFormula = `{OperationId} = "${operationId.replace(/"/g, '\\"')}"`;

return [{
  json: {
    ok: true,
    operationId,
    sale: {
      createdAt: sale.createdAt || new Date().toISOString(),
      customerId: sale.customerId || null,
      customerName: sale.customerName || 'Consumidor final',
      paymentMethod,
      cashReceived,
      subtotal,
      discountPercent,
      discountAmount,
      total,
      cashier: sale.cashier || null,
      cajaSesionId: sale.cajaSesionId || sale.cajaId || null,
      empresaId: sale.empresaId || null,
      source: sale.source || 'pos',
      items: normalizedItems
    },
    duplicateFormula,
    productFormula
  }
}];

const validation = $items('Validar Payload')[0].json;
const duplicate = $items('Buscar Venta OperationId').find(item => item.json && item.json.id);

if (!duplicate) {
  return [{ json: { ...validation, decision: 'create' } }];
}

const fields = duplicate.json.fields || duplicate.json;
const estado = fields.Estado || '';
const total = Number(fields.Total || validation.sale.total || 0);

if (String(estado).toUpperCase() === 'CONFIRMADA') {
  return [{ json: { ok: true, decision: 'duplicate-confirmed', operationId: validation.operationId, ventaId: duplicate.json.id, total, message: 'Venta ya registrada anteriormente.' } }];
}

return [{ json: { ok: false, decision: 'duplicate-blocked', operationId: validation.operationId, ventaId: duplicate.json.id, total, status: estado || 'Pendiente', message: 'Ya existe una venta con este OperationId y no se creara un duplicado.' } }];

const validation = $items('Resolver Idempotencia')[0].json;
const sale = validation.sale;
const products = $items('Buscar Productos').filter(item => item.json && item.json.id);
const productMap = new Map(products.map(item => [item.json.id, item.json.fields || item.json]));
const errors = [];
const detailRows = [];
const stockRows = [];
const stockUpdates = [];
const serverItems = [];

function number(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function textValue(value) {
  if (value && typeof value === 'object' && 'text' in value) return String(value.text || '');
  return String(value || '');
}

for (const item of sale.items) {
  const record = productMap.get(item.productId);
  if (!record) {
    errors.push({ productId: item.productId, message: 'Producto no encontrado.' });
    continue;
  }

  const stockBefore = number(record['Stock Actual']);
  const serverPrice = number(record.Importe, number(record['Precio x Kg']));
  const quantity = number(item.quantity);

  if (!Number.isFinite(stockBefore) || stockBefore <= 0) {
    errors.push({ productId: item.productId, available: stockBefore, requested: quantity, message: 'Producto sin stock disponible.' });
    continue;
  }

  if (stockBefore < quantity) {
    errors.push({ productId: item.productId, available: stockBefore, requested: quantity, message: 'Stock insuficiente.' });
    continue;
  }

  if (!Number.isFinite(serverPrice) || serverPrice <= 0) {
    errors.push({ productId: item.productId, message: 'Producto sin precio valido.' });
    continue;
  }

  const productName = String(record.Name || item.name || 'Producto');
  const barcode = textValue(record['Codigo de Barras'] || item.barcode);
  const weight = number(record.Peso, number(item.weight));
  const lineTotal = serverPrice * quantity;
  const stockAfter = stockBefore - quantity;

  serverItems.push({ ...item, name: productName, barcode, unitPrice: serverPrice, weight, lineTotal });
  detailRows.push({ Venta: null, OperationId: validation.operationId, Producto: [item.productId], ProductoNombre: productName, CodigoBarras: barcode, Cantidad: quantity, PrecioUnitario: serverPrice, Peso: weight, SubtotalLinea: lineTotal, DescuentoLinea: 0, TotalLinea: lineTotal, StockAntes: stockBefore, StockDespues: stockAfter, Estado: 'ACTIVO', Fecha: sale.createdAt });
  stockRows.push({ OperationId: validation.operationId, Fecha: sale.createdAt, Producto: [item.productId], ProductoNombre: productName, Tipo: 'VENTA', Cantidad: -quantity, StockAntes: stockBefore, StockDespues: stockAfter, Motivo: 'Venta POS', Origen: 'POS', Venta: null, DetalleVenta: null, Responsable: sale.cashier || '', Estado: 'ACTIVO', Notas: '' });
  stockUpdates.push({ id: item.productId, fields: { 'Stock Actual': stockAfter }, stockBefore, stockAfter });
}

if (errors.length > 0) {
  return [{ json: { ok: false, operationId: validation.operationId, status: 'Rechazada', message: 'No se pudo validar la venta.', details: errors } }];
}

const subtotal = serverItems.reduce((sum, item) => sum + item.lineTotal, 0);
const discountAmount = subtotal * (sale.discountPercent / 100);
const total = subtotal - discountAmount;

if (Math.abs(Number(sale.subtotal) - subtotal) > 1 || Math.abs(Number(sale.total) - total) > 1) {
  return [{ json: { ok: false, operationId: validation.operationId, status: 'Rechazada', message: 'El total de la venta no coincide con los precios actuales del servidor.' } }];
}

sale.items = serverItems;
sale.subtotal = subtotal;
sale.discountAmount = discountAmount;
sale.total = total;

return [{ json: { ok: true, operationId: validation.operationId, sale, detailRows, stockRows, stockUpdates } }];

const saleData = $items('Validar Stock y Totales')[0].json;
const saleRecord = $items('Crear Venta Pendiente')[0].json;
if (!saleRecord || saleRecord.error || !saleRecord.id) {
  return [{ json: { ok: false, step: 'Crear Venta Pendiente', operationId: saleData.operationId, message: 'No se pudo crear la venta pendiente.', created: {}, stockUpdates: [] } }];
}
return saleData.detailRows.map(row => ({ json: { ...row, Venta: [saleRecord.id] } }));

const saleData = $items('Validar Stock y Totales')[0].json;
const saleRecord = $items('Crear Venta Pendiente')[0].json;
const detailItems = $items('Crear Detalle Venta');
const detailRecords = detailItems.filter(item => item.json && item.json.id && !item.json.error);
if (detailRecords.length !== saleData.detailRows.length) {
  return [{ json: { ok: false, step: 'Crear Detalle Venta', operationId: saleData.operationId, ventaId: saleRecord.id, message: 'No se pudo crear todo el detalle de venta.', created: { ventaId: saleRecord.id, detailIds: detailRecords.map(item => item.json.id) }, stockUpdates: [] } }];
}
return saleData.stockRows.map((row, index) => ({ json: { ...row, Venta: [saleRecord.id], DetalleVenta: [detailRecords[index].json.id] } }));

const saleData = $items('Validar Stock y Totales')[0].json;
const saleRecord = $items('Crear Venta Pendiente')[0].json;
const detailRecords = $items('Crear Detalle Venta').filter(item => item.json && item.json.id && !item.json.error);
const stockRecords = $items('Crear Movimientos Stock').filter(item => item.json && item.json.id && !item.json.error);
if (stockRecords.length !== saleData.stockRows.length) {
  return [{ json: { ok: false, step: 'Crear Movimientos Stock', operationId: saleData.operationId, ventaId: saleRecord.id, message: 'No se pudieron crear todos los movimientos de stock.', created: { ventaId: saleRecord.id, detailIds: detailRecords.map(item => item.json.id), stockMovementIds: stockRecords.map(item => item.json.id) }, stockUpdates: [] } }];
}
return saleData.stockUpdates.map(update => ({ json: { id: update.id, 'Stock Actual': update.fields['Stock Actual'], stockBefore: update.stockBefore, stockAfter: update.stockAfter } }));

const saleData = $items('Validar Stock y Totales')[0].json;
const saleRecord = $items('Crear Venta Pendiente')[0].json;
const updated = $items('Actualizar Stock Produccion').filter(item => item.json && item.json.id && !item.json.error);
if (updated.length !== saleData.stockUpdates.length) {
  return [{ json: { ok: false, step: 'Actualizar Stock Produccion', operationId: saleData.operationId, ventaId: saleRecord.id, message: 'No se pudo actualizar todo el stock. Se intentara restaurar el stock anterior.', created: { ventaId: saleRecord.id }, stockUpdates: saleData.stockUpdates } }];
}
const sale = saleData.sale;
if (!sale.cajaSesionId) {
  return [{ json: { ok: false, step: 'Validar Caja', operationId: saleData.operationId, ventaId: saleRecord.id, message: 'La venta no tiene sesion de caja confirmada.', created: { ventaId: saleRecord.id }, stockUpdates: saleData.stockUpdates } }];
}
return [{ json: { id: 'mov-' + saleData.operationId, empresa_id: sale.empresaId || '', caja_sesion_id: sale.cajaSesionId, usuario_id: sale.cashier || '', venta_id: saleRecord.id, tipo: 'INGRESO', origen: 'VENTA', importe: sale.total, estado: 'ACTIVO', motivo: 'Venta POS', operation_id: saleData.operationId, fecha_hora: sale.createdAt } }];

const saleData = $items('Validar Stock y Totales')[0].json;
const saleRecord = $items('Crear Venta Pendiente')[0].json;
const cajaRecord = $items('Crear Movimiento Caja')[0].json;
if (!cajaRecord || cajaRecord.error || !cajaRecord.id) {
  return [{ json: { ok: false, step: 'Crear Movimiento Caja', operationId: saleData.operationId, ventaId: saleRecord.id, message: 'No se pudo crear el movimiento de caja. Se intentara restaurar el stock anterior.', created: { ventaId: saleRecord.id }, stockUpdates: saleData.stockUpdates } }];
}
return [{ json: { id: saleRecord.id, Estado: 'CONFIRMADA', CajaMovimiento: [cajaRecord.id], FechaConfirmacion: new Date().toISOString(), ErrorMensaje: '' } }];

const failed = $json;
const operationId = failed.operationId || 'sin-operation-id';
const stockUpdates = Array.isArray(failed.stockUpdates) ? failed.stockUpdates : [];
const cajaMovimientoId = failed.cajaMovimientoId || failed.created?.cajaMovimientoId || null;
const errorMessage = (failed.step || 'Error') + ': ' + (failed.message || 'Error durante la venta');
return [{ json: { ok: false, operationId, rollbackStatus: stockUpdates.length > 0 || cajaMovimientoId ? 'CompensacionPendiente' : 'RollbackPendiente', message: failed.message || 'La venta no pudo completarse. Revisar operacion en n8n.', failedStep: failed.step || 'desconocido', ventaId: failed.ventaId || failed.created?.ventaId || null, cajaMovimientoId, stockUpdates, errorFields: { Estado: 'RollbackPendiente', ErrorMensaje: errorMessage } } }];

const saleData = $items('Validar Stock y Totales')[0].json;
const saleRecord = $items('Crear Venta Pendiente')[0].json;
const cajaRecord = $items('Crear Movimiento Caja')[0].json;
const confirmation = $items('Confirmar Venta')[0].json;
if (!confirmation || confirmation.error || !confirmation.id) {
  return [{ json: { ok: false, step: 'Confirmar Venta', operationId: saleData.operationId, ventaId: saleRecord.id, message: 'La venta no pudo confirmarse despues de escribir caja. Se intentara compensar stock y caja.', created: { ventaId: saleRecord.id, cajaMovimientoId: cajaRecord && cajaRecord.id ? cajaRecord.id : null }, stockUpdates: saleData.stockUpdates } }];
}
return [{ json: { ok: true, ventaId: saleRecord.id, operationId: saleData.operationId, total: saleData.sale.total } }];

const rollback = $items('Preparar Rollback')[0].json;
const stockUpdates = Array.isArray(rollback.stockUpdates) ? rollback.stockUpdates : [];
if (stockUpdates.length === 0) {
  return [{ json: { ok: true, skipStockRestore: true, operationId: rollback.operationId, ventaId: rollback.ventaId } }];
}
return stockUpdates.map(update => ({ json: { id: update.id, 'Stock Actual': update.stockBefore, operationId: rollback.operationId, ventaId: rollback.ventaId } }));

const rollback = $items('Preparar Rollback')[0].json;
if (!rollback.cajaMovimientoId) {
  return [{ json: { ok: true, skipCajaCancel: true, operationId: rollback.operationId, ventaId: rollback.ventaId } }];
}
return [{ json: { id: rollback.cajaMovimientoId, estado: 'ANULADO', motivo: 'Anulado automaticamente por rollback de venta ' + rollback.operationId, operationId: rollback.operationId, ventaId: rollback.ventaId } }];

const rollback = $items('Preparar Rollback')[0].json;
if (!rollback.ventaId) {
  return [{ json: { skipVentaRollback: true, operationId: rollback.operationId } }];
}
return [{ json: { id: rollback.ventaId, Estado: 'ERROR', ErrorMensaje: rollback.errorFields?.ErrorMensaje || rollback.message || 'Rollback pendiente', operationId: rollback.operationId } }];
